#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

// =====================================================
// FORWARD BUTTON
// =====================================================

#define FORWARD_BUTTON 13

// =====================================================
// SPEED
// =====================================================

#define FORWARD_SPEED 128   // 50%

// =====================================================
// TIMING
// =====================================================

#define DISCOVERY_INTERVAL 1000
#define COMMAND_INTERVAL 50

unsigned long lastDiscovery = 0;
unsigned long lastCommand = 0;

// =====================================================
// CAR ADDRESS
// =====================================================

uint8_t carAddress[6];
bool carFound = false;

// =====================================================
// COMMAND PACKET
// Must match the car
// =====================================================

struct CommandPacket {
  char command;
  uint8_t speed;
};

// =====================================================
// ADD CAR
// =====================================================

bool addCarPeer() {

  if (esp_now_is_peer_exist(carAddress)) {
    return true;
  }

  esp_now_peer_info_t peerInfo = {};

  memcpy(
    peerInfo.peer_addr,
    carAddress,
    6
  );

  peerInfo.channel = 1;
  peerInfo.encrypt = false;

  return esp_now_add_peer(&peerInfo) == ESP_OK;
}

// =====================================================
// SEND COMMAND
// =====================================================

void sendCommand(char command, uint8_t speed) {

  if (!carFound) {
    return;
  }

  CommandPacket packet;

  packet.command = command;
  packet.speed = speed;

  esp_now_send(
    carAddress,
    (uint8_t *)&packet,
    sizeof(packet)
  );
}

// =====================================================
// RECEIVE FROM CAR
// =====================================================

void onDataReceive(
  const esp_now_recv_info_t *info,
  const uint8_t *data,
  int len
) {

  if (len >= 3 && memcmp(data, "CAR", 3) == 0) {

    memcpy(
      carAddress,
      info->src_addr,
      6
    );

    if (addCarPeer()) {

      carFound = true;

      Serial.println();
      Serial.println("==============================");
      Serial.println("CAR FOUND");
      Serial.println("CONTROLLER CONNECTED");
      Serial.println("==============================");
    }
  }
}

// =====================================================
// SEARCH FOR CAR
// =====================================================

void searchForCar() {

  uint8_t broadcastAddress[] = {
    0xFF,
    0xFF,
    0xFF,
    0xFF,
    0xFF,
    0xFF
  };

  if (!esp_now_is_peer_exist(broadcastAddress)) {

    esp_now_peer_info_t peerInfo = {};

    memcpy(
      peerInfo.peer_addr,
      broadcastAddress,
      6
    );

    peerInfo.channel = 1;
    peerInfo.encrypt = false;

    esp_now_add_peer(&peerInfo);
  }

  const char hello[] = "HELLO";

  esp_now_send(
    broadcastAddress,
    (uint8_t *)hello,
    sizeof(hello)
  );

  Serial.println("Searching for car...");
}

// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  // Forward button
  // Button connects GPIO 13 to GND
  pinMode(
    FORWARD_BUTTON,
    INPUT_PULLUP
  );

  WiFi.mode(WIFI_STA);

  esp_wifi_set_channel(
    1,
    WIFI_SECOND_CHAN_NONE
  );

  Serial.println();
  Serial.println("==============================");
  Serial.println("FORWARD BUTTON TEST");
  Serial.println("==============================");

  if (esp_now_init() != ESP_OK) {

    Serial.println("ESP-NOW FAILED!");

    while (true) {
      delay(1000);
    }
  }

  esp_now_register_recv_cb(onDataReceive);

  Serial.println("ESP-NOW READY");
  Serial.println("Searching for car...");
}

// =====================================================
// LOOP
// =====================================================

void loop() {

  // ---------------------------------------------------
  // Find car
  // ---------------------------------------------------

  if (!carFound) {

    if (
      millis() - lastDiscovery >=
      DISCOVERY_INTERVAL
    ) {

      lastDiscovery = millis();

      searchForCar();
    }

    delay(10);
    return;
  }

  // ---------------------------------------------------
  // FORWARD BUTTON
  // ---------------------------------------------------

  if (
    digitalRead(FORWARD_BUTTON) == LOW
  ) {

    if (
      millis() - lastCommand >=
      COMMAND_INTERVAL
    ) {

      lastCommand = millis();

      sendCommand(
        'F',
        FORWARD_SPEED
      );

      Serial.println("FORWARD");
    }
  }

  // ---------------------------------------------------
  // BUTTON RELEASED = STOP
  // ---------------------------------------------------

  else {

    if (
      millis() - lastCommand >=
      COMMAND_INTERVAL
    ) {

      lastCommand = millis();

      sendCommand(
        'S',
        0
      );
    }
  }

  delay(5);
}
